/// One match in one file.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct FileHit {
    pub path: std::path::PathBuf,
    pub line: u32,
    pub col: u32,
    /// The line text without its line break.
    pub text: String,
}

#[derive(Debug)]
pub enum FileSearchError {
    Io { path: std::path::PathBuf, message: String },
    Binary { path: std::path::PathBuf },
    Search(SearchError),
}
